<!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Ulasan | <?= esc($businessName) ?></title><link rel="stylesheet" href="<?= base_url('assets/css/app.css') ?>"></head><body class="min-h-screen bg-surface-cream text-brand-cocoa antialiased"><a class="skip-link" href="#konten">Lewati ke formulir</a><header class="border-b border-brand-cocoa bg-brand-sun"><div class="mx-auto flex max-w-4xl items-center justify-between px-4 py-5 sm:px-6"><a class="font-display text-xl focus-ring" href="<?= site_url('/') ?>"><?= esc($businessName) ?></a><span class="text-sm font-bold">Ulasan pembelian</span></div></header><main id="konten" class="mx-auto max-w-4xl px-4 py-10 sm:px-6 sm:py-16">
<div class="grid gap-8 lg:grid-cols-[.8fr_1.2fr] lg:items-start"><section><p class="section-kicker">Terima kasih sudah membeli</p><h1 class="mt-3 font-display text-4xl leading-tight">Bagaimana rasa pilihan Anda?</h1><p class="mt-4 leading-7 text-ink-muted">Ulasan membantu pelanggan lain memilih. Nama, komentar, dan foto yang disetujui akan tampil di halaman produk.</p><div class="mt-6 border border-brand-cocoa bg-brand-sun p-5 text-sm"><strong class="block">Transaksi <?= esc($context['token']['sale_number']) ?></strong><span class="mt-1 block">Tautan berlaku sampai <?= esc(date('d/m/Y H:i', strtotime($context['token']['expires_at']))) ?></span></div></section>
<section class="panel-card p-5 sm:p-7"><?php if (session()->getFlashdata('review_success')): ?><div class="alert-success mb-5" role="status"><?= esc(session()->getFlashdata('review_success')) ?></div><?php endif ?><?php if (session()->getFlashdata('review_error')): ?><div class="alert-danger mb-5" role="alert"><?= esc(session()->getFlashdata('review_error')) ?></div><?php endif ?><?php $available = array_values(array_filter($context['items'], static fn(array $item): bool => !$item['review_id'])); ?><?php if ($available === []): ?><h2 class="font-display text-2xl">Semua produk sudah diulas.</h2><p class="mt-3 text-ink-muted">Terima kasih. Ulasan akan tampil setelah diperiksa oleh owner.</p><a class="button-secondary mt-5" href="<?= site_url('/') ?>">Kembali ke menu</a><?php else: ?><form action="<?= site_url('ulasan/' . $token) ?>" method="post" enctype="multipart/form-data" class="space-y-5"><?= csrf_field() ?><div class="absolute -left-[9999px]" aria-hidden="true"><label for="website">Website</label><input id="website" name="website" type="text" tabindex="-1" autocomplete="off"></div><div><label class="form-label" for="review-item">Produk</label><select class="form-input" id="review-item" name="sale_item_id" required><option value="">Pilih produk</option><?php foreach ($available as $item): ?><option value="<?= (int) $item['id'] ?>" <?= (int) old('sale_item_id') === (int) $item['id'] ? 'selected' : '' ?>><?= esc($item['product_name'] . ' · ' . $item['variant_name']) ?></option><?php endforeach ?></select></div><fieldset><legend class="form-label">Rating</legend><div class="grid grid-cols-5 gap-2"><?php foreach ([1,2,3,4,5] as $rating): ?><label class="grid min-h-14 cursor-pointer place-items-center border border-border-warm bg-surface-soft-yellow text-sm font-bold has-[:checked]:border-brand-cocoa has-[:checked]:bg-brand-sun"><input class="sr-only" type="radio" name="rating" value="<?= $rating ?>" <?= (int) old('rating') === $rating ? 'checked' : '' ?> required><span aria-hidden="true">★ <?= $rating ?></span><span class="sr-only"><?= $rating ?> dari 5</span></label><?php endforeach ?></div></fieldset><div><label class="form-label" for="review-name">Nama tampilan <span class="font-normal text-ink-muted">(opsional)</span></label><input class="form-input" id="review-name" name="display_name" value="<?= esc(old('display_name')) ?>" maxlength="80" placeholder="Anonim jika dikosongkan"></div><div><label class="form-label" for="review-comment">Komentar</label><textarea class="form-input min-h-32" id="review-comment" name="comment" minlength="10" maxlength="1000" required><?= esc(old('comment')) ?></textarea><p class="mt-1 text-xs text-ink-muted">Ceritakan rasa, porsi, atau pengalaman Anda tanpa mencantumkan data pribadi.</p></div><div><label class="form-label" for="review-photos">Foto <span class="font-normal text-ink-muted">(opsional, maksimal 3)</span></label><input class="form-input file:mr-3 file:border-0 file:bg-brand-sun file:px-3 file:py-2 file:font-bold" id="review-photos" name="photos[]" type="file" accept="image/jpeg,image/png,image/webp" multiple><p class="mt-1 text-xs text-ink-muted">Maksimal 2 MB per foto. Metadata lokasi akan dihapus.</p></div><?php if ($captcha): ?><div class="border border-brand-cocoa bg-brand-sun p-4"><label class="form-label" for="captcha-answer">Verifikasi: berapa <?= esc($captcha) ?>?</label><input class="form-input" id="captcha-answer" name="captcha_answer" type="number" required></div><?php endif ?><label class="flex items-start gap-3 text-sm leading-6"><input class="mt-1 h-5 w-5 shrink-0 accent-brand-cocoa" type="checkbox" required><span>Saya memahami bahwa nama tampilan, komentar, dan foto yang disetujui akan ditampilkan secara publik.</span></label><button class="button-primary w-full" type="submit">Kirim ulasan</button></form><?php endif ?></section></div></main></body></html>
